# Sourced by oblimint-relay-entrypoint / oblimint-relay-reload.
#
# apply_overrides FILE: applies the "key = value" lines of the panel-written
# postfix.cf with postconf -e, for an ALLOW-LIST of keys and values made of
# host name / address characters only (the file is generated by the panel —
# server/src/services/mail/outbound/relayConfig.ts renderRelayPostfixOverrides
# — but it is still never trusted to inject arbitrary Postfix settings).
apply_overrides() {
	file=$1
	[ -f "$file" ] || return 0
	while IFS= read -r line || [ -n "$line" ]; do
		case "$line" in '' | '#'*) continue ;; esac
		key=$(printf '%s' "$line" | sed -n 's/^\([a-z_]*\)[[:space:]]*=.*$/\1/p')
		value=$(printf '%s' "$line" | sed -n 's/^[a-z_]*[[:space:]]*=[[:space:]]*\(.*\)$/\1/p')
		case "$key" in
			myhostname | relayhost | message_size_limit | smtp_tls_security_level) ;;
			*) echo "oblimint-relay: ignored override key '$key'" >&2; continue ;;
		esac
		# `]` first and `-` last are literal in a bracket expression on every
		# POSIX sh; a backslash-escaped `\]` ENDS the bracket in busybox ash,
		# and the pattern then never matched (`a;b`, `x y` went through).
		case "$value" in
			*[!]A-Za-z0-9.:_[-]*) echo "oblimint-relay: ignored override value for $key" >&2; continue ;;
		esac
		postconf -e "$key = $value"
	done < "$file"
}
